typedef float time_value_t;

class FEMenu
{
public:
	void Update(time_value_t time_inc);
};

class FrontEnd
{
public:
	void Update(time_value_t time_inc);
};

class FEMultiMenu : public FEMenu
{
	char front_end_offset[0x7c];
public:
	void Update(time_value_t time_inc)
	{
		((FrontEnd *) ((char *) this + 0x80))->Update(time_inc);
		FEMenu::Update(time_inc);
	}
};

class SaveLoadFrontEnd
{
	char pad[0x32c4];
	int dstate;
public:
	enum
	{
		DSTATE_LOADING = 5,
		DSTATE_DELETING = 11,
		DSTATE_SAVING = 18,
		DSTATE_FORMATTING = 20
	};

	bool Busy()
	{
		return (dstate == DSTATE_SAVING || dstate == DSTATE_LOADING || dstate == DSTATE_DELETING || dstate == DSTATE_FORMATTING);
	}
	bool DialogActive();
	void CancelDialog();
};

struct MemCard
{
	int free;
	bool exists;
	bool changed;
	bool available;
	bool ask_format;
	bool saved_games;
	char pad[3];
	int status;
	char tail[12];
};

class NamesMenu : public FEMultiMenu
{
	char pad0[0xe8];
	SaveLoadFrontEnd* sl_parent;
	int check_cards_counter;
	char pad1[0x44];
	MemCard cards[2];
	char pad2[8];
	int active_card;
	int adjusted_active_card;

	void CheckCardNum(int c);
	void UpdateMessage();
public:
	void MakeSpaceFreeMessage(int freeBytes);
	void RefreshDisplay();
	void Update(time_value_t time_inc);
};

__asm__(".equ Update__8FrontEndf, 0x00157B30");
__asm__(".equ Update__6FEMenuf, 0x00156DC8");
__asm__(".equ CheckCardNum__9NamesMenui, 0x001A0470");
__asm__(".equ MakeSpaceFreeMessage__9NamesMenui, 0x0019E790");
__asm__(".equ DialogActive__16SaveLoadFrontEnd, 0x0019BF38");
__asm__(".equ CancelDialog__16SaveLoadFrontEnd, 0x0019BF00");
__asm__(".equ RefreshDisplay__9NamesMenu, 0x0019FF58");
__asm__(".equ UpdateMessage__9NamesMenu, 0x0019FDD0");

void NamesMenu::Update(time_value_t time_inc)
{
	if(sl_parent->Busy()) return;

	// execute CheckCurrentCard only every 10 times, because it's slow
	check_cards_counter++;
	if(check_cards_counter >= 10)
	{
		CheckCardNum(active_card);
		MakeSpaceFreeMessage(cards[adjusted_active_card].free);
		check_cards_counter = 0;
	}

	// if the card that previously needed formatting has been pulled out, end
	// the format loop
/*	if(!cards[adjusted_active_card].exists && cards[adjusted_active_card].changed && !cards[adjusted_active_card].available)
		AskFormat(false);*/

	if(cards[adjusted_active_card].changed && !cards[adjusted_active_card].exists && sl_parent->DialogActive())
		sl_parent->CancelDialog();

#ifdef TARGET_XBOX	// Not supposed to display empty memory unit slots on Xbox (dc 07/07/02)
	if(!cards[adjusted_active_card].exists)
	{
		OnRight(0);
	}
#endif

	// if card has been put in or pulled out
	if(cards[adjusted_active_card].changed)
		RefreshDisplay();

	if (!sl_parent->DialogActive())
		UpdateMessage();
	FEMultiMenu::Update(time_inc);
}
